uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 toLayer;
uniform float3x3 fromLayer;
uniform float time;
uniform float amount;
uniform float seed;
float4 readInput(float2 uv){if(uv.x<0.0||uv.y<0.0||uv.x>1.0||uv.y>1.0)return float4(0.0);return float4(image.eval(uv * size));}
float hash(float2 p){return fract(sin(dot(p,float2(127.1,311.7))+seed)*43758.5453);}half4 main(float2 coord){float2 uv=(coord / size);float a=hash(floor(uv*800.0))*6.2831853;float2 d=float2(cos(a),sin(a))*amount;return (readInput(uv+d)+readInput(uv-d)+readInput(uv)) / 3.0;}
